const input = $json.body ?? $json;

const text = (value) =>
  value === null || value === undefined
    ? ''
    : String(value).trim();

const bool = (value) =>
  typeof value === 'boolean'
    ? value
    : ['true', '1', 'yes', 'on'].includes(
        text(value).toLowerCase()
      );

const clinic_name = text(input.clinic_name);
const warning_queue_threshold =
  Number(input.warning_queue_threshold ?? 100);
const critical_queue_threshold =
  Number(input.critical_queue_threshold ?? 500);
const stale_processing_minutes =
  Number(input.stale_processing_minutes ?? 15);
const error_window_hours =
  Number(input.error_window_hours ?? 24);
const confirm_check = bool(input.confirm_check);

const errors = [];

if (
  !Number.isInteger(warning_queue_threshold) ||
  warning_queue_threshold < 1 ||
  warning_queue_threshold > 100000
) {
  errors.push({
    field: 'warning_queue_threshold',
    message: 'آستانه هشدار صف معتبر نیست.',
  });
}

if (
  !Number.isInteger(critical_queue_threshold) ||
  critical_queue_threshold <= warning_queue_threshold ||
  critical_queue_threshold > 1000000
) {
  errors.push({
    field: 'critical_queue_threshold',
    message: 'آستانه بحرانی باید از آستانه هشدار بزرگ‌تر باشد.',
  });
}

if (
  !Number.isInteger(stale_processing_minutes) ||
  stale_processing_minutes < 5 ||
  stale_processing_minutes > 1440
) {
  errors.push({
    field: 'stale_processing_minutes',
    message: 'بازه پیام‌های Stale معتبر نیست.',
  });
}

if (
  !Number.isInteger(error_window_hours) ||
  error_window_hours < 1 ||
  error_window_hours > 720
) {
  errors.push({
    field: 'error_window_hours',
    message: 'بازه بررسی خطا معتبر نیست.',
  });
}

if (confirm_check !== true) {
  errors.push({
    field: 'confirm_check',
    message: 'بررسی سلامت باید تأیید شود.',
  });
}

return [{
  json: {
    clinic_name,
    warning_queue_threshold,
    critical_queue_threshold,
    stale_processing_minutes,
    error_window_hours,
    confirm_check,
    validation_status:
      errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];

if ($json.success !== true) {
  return [{
    json: {
      success: false,
      result: $json.result || 'health_context_failed',
      overall_status: 'unhealthy',
      checks: $json.checks || {},
      metrics: $json.metrics || {},
    },
  }];
}

const config =
  $('Normalize and Validate Health Check')
    .first().json;

const checks =
  $json.checks &&
  typeof $json.checks === 'object'
    ? $json.checks
    : {};

const metrics =
  $json.metrics &&
  typeof $json.metrics === 'object'
    ? $json.metrics
    : {};

const missingTables = Object.entries(checks)
  .filter(([, value]) => value !== true)
  .map(([key]) => key);

const queuedDue =
  Number(metrics.queued_due_count || 0);

const staleProcessing =
  Number(metrics.stale_processing_count || 0);

const deadLetters =
  Number(metrics.unresolved_dead_letter_count || 0);

const openErrors =
  Number(metrics.open_workflow_error_count || 0);

const criticalErrors =
  Number(metrics.critical_workflow_error_count || 0);

let overallStatus = 'healthy';
const reasons = [];

if (missingTables.length > 0) {
  overallStatus = 'unhealthy';
  reasons.push(
    `missing_tables:${missingTables.join(',')}`
  );
}

if (criticalErrors > 0) {
  overallStatus = 'unhealthy';
  reasons.push('critical_workflow_errors');
}

if (
  staleProcessing >
  config.critical_queue_threshold
) {
  overallStatus = 'unhealthy';
  reasons.push('stale_processing_critical');
}

if (
  deadLetters >
  config.critical_queue_threshold
) {
  overallStatus = 'unhealthy';
  reasons.push('dead_letter_critical');
}

if (
  queuedDue >
  config.critical_queue_threshold
) {
  overallStatus = 'unhealthy';
  reasons.push('queue_backlog_critical');
}

if (
  overallStatus === 'healthy' &&
  (
    queuedDue >
      config.warning_queue_threshold ||
    staleProcessing > 0 ||
    deadLetters > 0 ||
    openErrors > 0
  )
) {
  overallStatus = 'degraded';

  if (
    queuedDue >
    config.warning_queue_threshold
  ) {
    reasons.push('queue_backlog_warning');
  }

  if (staleProcessing > 0) {
    reasons.push('stale_processing_detected');
  }

  if (deadLetters > 0) {
    reasons.push('unresolved_dead_letters');
  }

  if (openErrors > 0) {
    reasons.push('open_workflow_errors');
  }
}

if (reasons.length === 0) {
  reasons.push('all_checks_passed');
}

return [{
  json: {
    success: true,
    result: 'system_health_evaluated',
    clinic_id:
      Number($json.clinic_id || 0),
    clinic_name:
      $json.clinic_name || '',
    postgres_version:
      $json.postgres_version,
    checked_at:
      $json.checked_at,
    overall_status: overallStatus,
    health_reasons: reasons,
    checks,
    checks_text:
      JSON.stringify(checks),
    metrics,
    metrics_text:
      JSON.stringify({
        ...metrics,
        health_reasons: reasons,
      }),
  },
}];
